-- Consolidate subscription plan pricing, one-time canteen trials, configured billing cycles,
-- member pricing slabs, canteen-level fixed overrides, and authoritative billing quotes.
create table if not exists public.subscription_plan_ranges (
  id uuid primary key default gen_random_uuid(),
  plan_id uuid not null references public.subscription_plans(id) on delete cascade,
  min_members integer not null check (min_members >= 0),
  max_members integer not null check (max_members >= min_members),
  monthly_price numeric(12,2) not null check (monthly_price >= 0),
  annual_price numeric(12,2) not null check (annual_price >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists subscription_plan_ranges_plan_members_idx on public.subscription_plan_ranges(plan_id,min_members,max_members);
alter table public.subscription_plan_ranges enable row level security;
alter table public.subscription_plans add column if not exists billing_cycle text not null default 'monthly';
alter table public.subscription_plans drop constraint if exists subscription_plans_billing_cycle_check;
alter table public.subscription_plans add constraint subscription_plans_billing_cycle_check check (billing_cycle in ('monthly','annual'));
alter table public.canteen_subscriptions add column if not exists trial_used_at timestamptz null, add column if not exists effective_amount_override numeric(12,2) null;
alter table public.canteen_subscriptions drop constraint if exists canteen_subscriptions_effective_amount_override_check;
alter table public.canteen_subscriptions add constraint canteen_subscriptions_effective_amount_override_check check (effective_amount_override is null or effective_amount_override >= 0);
alter table public.subscription_payment_settings add column if not exists vendor_contact_email text;
update public.subscription_payment_settings set vendor_contact_email=coalesce(nullif(trim(vendor_contact_email),''),'gocanteen1729@gmail.com') where id=true;
insert into public.subscription_plan_ranges(plan_id,min_members,max_members,monthly_price,annual_price)
select p.id,p.min_members,p.max_members,p.monthly_price,p.annual_price from public.subscription_plans p where p.pricing_model='MEMBER_RANGE' and not exists(select 1 from public.subscription_plan_ranges r where r.plan_id=p.id);
update public.subscription_plans set billing_cycle=case when billing_period='yearly' then 'annual' else 'monthly' end where billing_cycle is null or billing_cycle not in ('monthly','annual');
update public.canteen_subscriptions set trial_used_at=coalesce(trial_used_at,trial_start,created_at) where trial_used_at is null;
create or replace function public.resolve_member_range_plan(p_canteen_id uuid) returns uuid language sql stable set search_path='' as $$ select p.id from public.subscription_plans p join public.subscription_plan_ranges r on r.plan_id=p.id where p.active and p.pricing_model='MEMBER_RANGE' and r.min_members <= (select count(*)::integer from public.profiles e where e.canteen_id=p_canteen_id and e.role='employee' and e.status='active') and r.max_members >= (select count(*)::integer from public.profiles e where e.canteen_id=p_canteen_id and e.role='employee' and e.status='active') order by r.min_members desc,p.created_at asc limit 1 $$;
create or replace function public.get_subscription_billing_quote(p_canteen_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare s public.canteen_subscriptions; p public.subscription_plans; r public.subscription_plan_ranges; v_members integer; v_cycle text; v_amount numeric(12,2); v_contact text; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not(public.is_super_admin() or public.current_canteen_id()=p_canteen_id) then raise exception 'Not authorized'; end if; select * into s from public.canteen_subscriptions where canteen_id=p_canteen_id; if not found then return jsonb_build_object('required',false,'reason','unassigned'); end if; select count(*)::integer into v_members from public.profiles e where e.canteen_id=p_canteen_id and e.role='employee' and e.status='active'; select * into p from public.subscription_plans where id=s.plan_id and active; if not found then raise exception 'Active subscription plan not found'; end if; v_cycle:=case when p.pricing_model='FIXED_AMOUNT' then 'monthly' else p.billing_cycle end; select coalesce(nullif(trim(vendor_contact_email),''),'gocanteen1729@gmail.com') into v_contact from public.subscription_payment_settings where id=true; v_contact:=coalesce(v_contact,'gocanteen1729@gmail.com'); if p.pricing_model='FIXED_AMOUNT' then v_amount:=coalesce(s.effective_amount_override,p.monthly_price); return jsonb_build_object('required',true,'plan_id',p.id,'plan_name',p.name,'pricing_model',p.pricing_model,'billing_cycle',v_cycle,'amount',v_amount,'currency',p.currency,'member_count',v_members,'max_exceeded',false,'contact_email',v_contact,'message',null); end if; select * into r from public.subscription_plan_ranges x where x.plan_id=p.id and x.min_members<=v_members and x.max_members>=v_members order by x.min_members desc limit 1; if not found then return jsonb_build_object('required',false,'plan_id',p.id,'plan_name',p.name,'pricing_model',p.pricing_model,'billing_cycle',v_cycle,'amount',null,'currency',p.currency,'member_count',v_members,'max_exceeded',coalesce(v_members>(select max(x.max_members) from public.subscription_plan_ranges x where x.plan_id=p.id),true),'contact_email',v_contact,'message','Your current member count exceeds the configured pricing range. Please contact the administrator.'); end if; v_amount:=case when v_cycle='annual' then r.annual_price else r.monthly_price end; return jsonb_build_object('required',true,'plan_id',p.id,'plan_name',p.name,'pricing_model',p.pricing_model,'billing_cycle',v_cycle,'amount',v_amount,'currency',p.currency,'member_count',v_members,'min_members',r.min_members,'max_members',r.max_members,'max_exceeded',false,'contact_email',v_contact,'message',null); end $$;
create or replace function public.super_admin_upsert_subscription_plan(p_plan_id uuid default null,p_name text default null,p_description text default null,p_pricing_model text default 'MEMBER_RANGE',p_billing_cycle text default 'monthly',p_currency text default 'INR',p_monthly_price numeric default null,p_annual_price numeric default null,p_ranges jsonb default '[]'::jsonb,p_active boolean default true,p_is_default boolean default false) returns public.subscription_plans language plpgsql security definer set search_path='' as $$ declare v_plan public.subscription_plans; v_range jsonb; v_min integer; v_max integer; v_monthly numeric(12,2); v_annual numeric(12,2); begin if not public.is_super_admin() then raise exception 'Super Admin authorization required'; end if; if nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'Plan name is required'; end if; if p_pricing_model not in ('FIXED_AMOUNT','MEMBER_RANGE') then raise exception 'Invalid pricing model'; end if; if p_pricing_model='FIXED_AMOUNT' then if p_monthly_price is null or p_monthly_price<0 then raise exception 'Fixed monthly amount is required'; end if; p_billing_cycle:='monthly'; p_annual_price:=p_monthly_price; p_ranges:='[]'::jsonb; else if p_billing_cycle not in ('monthly','annual') then raise exception 'MEMBER_RANGE billing cycle must be monthly or annual'; end if; if jsonb_typeof(coalesce(p_ranges,'[]'::jsonb))<>'array' or jsonb_array_length(coalesce(p_ranges,'[]'::jsonb))=0 then raise exception 'At least one member pricing range is required'; end if; end if; if p_plan_id is null then insert into public.subscription_plans(name,description,pricing_model,min_members,max_members,monthly_price,annual_price,price,billing_period,currency,trial_days,active,is_default,billing_cycle) values(trim(p_name),nullif(trim(p_description),''),p_pricing_model,case when p_pricing_model='MEMBER_RANGE' then 0 else null end,case when p_pricing_model='MEMBER_RANGE' then 2147483647 else null end,coalesce(p_monthly_price,0),coalesce(p_annual_price,coalesce(p_monthly_price,0)),coalesce(p_monthly_price,0),'monthly',upper(trim(coalesce(p_currency,'INR'))),0,p_active,false,p_billing_cycle) returning * into v_plan; else select * into v_plan from public.subscription_plans where id=p_plan_id for update; if not found then raise exception 'Plan not found'; end if; update public.subscription_plans set name=trim(p_name),description=nullif(trim(p_description),''),pricing_model=p_pricing_model,billing_cycle=p_billing_cycle,currency=upper(trim(coalesce(p_currency,'INR'))),monthly_price=coalesce(p_monthly_price,monthly_price),annual_price=coalesce(p_annual_price,coalesce(p_monthly_price,annual_price)),price=coalesce(p_monthly_price,monthly_price),billing_period='monthly',active=p_active,updated_at=now() where id=v_plan.id returning * into v_plan; delete from public.subscription_plan_ranges where plan_id=v_plan.id; end if; if v_plan.pricing_model='MEMBER_RANGE' then for v_range in select value from jsonb_array_elements(coalesce(p_ranges,'[]'::jsonb)) loop v_min:=coalesce((v_range->>'min_members')::integer,(v_range->>'min')::integer); v_max:=coalesce((v_range->>'max_members')::integer,(v_range->>'max')::integer); v_monthly:=coalesce((v_range->>'monthly_price')::numeric,(v_range->>'price')::numeric); v_annual:=coalesce((v_range->>'annual_price')::numeric,v_monthly); if v_min is null or v_max is null or v_monthly is null or v_annual is null or v_min<0 or v_max<v_min or v_monthly<0 or v_annual<0 then raise exception 'Invalid member pricing range'; end if; if exists(select 1 from public.subscription_plan_ranges x where x.plan_id=v_plan.id and int4range(x.min_members,x.max_members+1,'[]') && int4range(v_min,v_max+1,'[]')) then raise exception 'Member pricing ranges cannot overlap'; end if; insert into public.subscription_plan_ranges(plan_id,min_members,max_members,monthly_price,annual_price) values(v_plan.id,v_min,v_max,v_monthly,v_annual); end loop; select min(min_members),max(max_members),min(monthly_price),min(annual_price) into v_plan.min_members,v_plan.max_members,v_plan.monthly_price,v_plan.annual_price from public.subscription_plan_ranges where plan_id=v_plan.id; update public.subscription_plans set min_members=v_plan.min_members,max_members=v_plan.max_members,monthly_price=v_plan.monthly_price,annual_price=v_plan.annual_price,price=v_plan.monthly_price,updated_at=now() where id=v_plan.id returning * into v_plan; else update public.subscription_plans set min_members=null,max_members=null,annual_price=monthly_price,price=monthly_price,billing_cycle='monthly',updated_at=now() where id=v_plan.id returning * into v_plan; end if; if p_is_default then update public.subscription_plans set is_default=false,updated_at=now() where is_default and id<>v_plan.id; update public.subscription_plans set is_default=true,updated_at=now() where id=v_plan.id returning * into v_plan; end if; return v_plan; end $$;
drop policy if exists "subscription_plan_ranges_super_admin_select" on public.subscription_plan_ranges;
create policy "subscription_plan_ranges_super_admin_select" on public.subscription_plan_ranges for select to authenticated using (public.is_super_admin());
revoke all on table public.subscription_plan_ranges from anon,authenticated;
grant select on table public.subscription_plan_ranges to authenticated;
revoke execute on function public.get_subscription_billing_quote(uuid) from public,anon;
grant execute on function public.get_subscription_billing_quote(uuid) to authenticated;
revoke execute on function public.super_admin_upsert_subscription_plan(uuid,text,text,text,text,text,numeric,numeric,jsonb,boolean,boolean) from public,anon,authenticated;
grant execute on function public.super_admin_upsert_subscription_plan(uuid,text,text,text,text,text,numeric,numeric,jsonb,boolean,boolean) to authenticated;
